-- FINAL 1.4 (safe): teacher_attendance had a non-partial UNIQUE(schedule_slot_id, session_date)
-- from 003, so a trashed (undone) attendance row blocked re-marking the session.
--
-- This migration is deliberately narrow:
--   * it identifies the ONE autogenerated unique constraint on exactly (schedule_slot_id, session_date);
--   * it asserts it exists (or that the replacement index already exists on an idempotent re-run);
--   * it lists all other unique constraints before/after and aborts if any of them disappear;
--   * it creates a partial unique index over live rows only.
DO $$
DECLARE
    target_name text;
    target_candidates text[];
    unique_before text[];
    unique_after text[];
    replacement_exists boolean;
    target_present_after boolean;
BEGIN
    SELECT array_agg(conname ORDER BY conname) INTO unique_before
    FROM pg_constraint
    WHERE conrelid = 'public.teacher_attendance'::regclass AND contype = 'u';

    SELECT array_agg(conname ORDER BY conname) INTO target_candidates
    FROM pg_constraint
    WHERE conrelid = 'public.teacher_attendance'::regclass
      AND contype = 'u'
      AND regexp_replace(pg_get_constraintdef(oid), '\s+', '', 'g')
          IN ('UNIQUE(schedule_slot_id,session_date)', 'UNIQUE(session_date,schedule_slot_id)');

    IF target_candidates IS NOT NULL AND array_length(target_candidates, 1) > 1 THEN
        RAISE EXCEPTION 'Refusing migration 034: more than one unique constraint matches (schedule_slot_id, session_date): %', target_candidates;
    END IF;

    target_name := target_candidates[1];
    SELECT to_regclass('public.ux_teacher_attendance_slot_date_live') IS NOT NULL INTO replacement_exists;

    IF target_name IS NULL THEN
        IF NOT replacement_exists THEN
            RAISE EXCEPTION 'Refusing migration 034: neither the old unique constraint nor the replacement partial index exists.';
        END IF;
    ELSE
        EXECUTE format('ALTER TABLE public.teacher_attendance DROP CONSTRAINT %I', target_name);
    END IF;

    SELECT array_agg(conname ORDER BY conname) INTO unique_after
    FROM pg_constraint
    WHERE conrelid = 'public.teacher_attendance'::regclass AND contype = 'u';

    -- Every unique constraint except the deliberate target must survive.
    IF unique_after IS NOT NULL AND unique_before IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM unnest(unique_before) AS old_name
            WHERE old_name <> COALESCE(target_name, '')
              AND NOT EXISTS (SELECT 1 FROM unnest(unique_after) AS new_name WHERE new_name = old_name)
        ) THEN
            RAISE EXCEPTION 'Refusing migration 034: dropping the target constraint also removed another unique constraint.';
        END IF;
    END IF;

    CREATE UNIQUE INDEX IF NOT EXISTS ux_teacher_attendance_slot_date_live
        ON public.teacher_attendance (schedule_slot_id, session_date)
        WHERE is_trashed = FALSE;

    SELECT EXISTS (
        SELECT 1 FROM pg_indexes
        WHERE schemaname = 'public' AND indexname = 'ux_teacher_attendance_slot_date_live'
    ) INTO replacement_exists;
    IF NOT replacement_exists THEN
        RAISE EXCEPTION 'Refusing migration 034: replacement partial index was not created.';
    END IF;
END $$;
